  tooltip: string;
  border: string;
  borderStrong: string;
  borderSelected: string;
  line: string;
  lineSoft: string;
  ink: string;
  secondary: string;
  /** Text that recedes: labels, hints, timestamps. */
  tertiary: string;
  disabled: string;
  inkDim: string;
  inkFaint: string;
  rest: string;
  /** Header actions and other glyphs that recede until hovered. */
  iconQuiet: string;
  accent: string;
